%map = loadMapdt(2,1)
map.vm
%%
ax = gca %[output:9e9bcdcd]
ax.Children.XData =map.vm %[output:6d3c6059] %[output:3215f989]
axis equal %[output:3215f989]
%%
%[text] 
for iph = 1:2
    map =loadMapdt(2+iph,1);
    mapXkills{iph} =  transpose(squeeze(mean(map.Gfinal0T)));
end
%%
close
views(mapXkills{iph}) %[output:39b8024d]
f = gcf %[output:6eee63a0]
f.Children.Children.XData =  %[output:329a7c5d]
%%
% for
tns = ["C-type" "A-type"] %[output:8274cb59]
for iph = 1:2 %[output:group:8e325e14]
    subplot(2,1,iph) %[output:8fe497a3]
    views(mapXkills{iph}) %[output:8fe497a3]
    xlabel("E")
    ylabel("y")
    sgtitle('x-component averaged map')
    colormap bone
    ax = gca %[output:71e57082] %[output:29384da3]
    axis image %[output:8fe497a3]
    ax.Children.XData =map.vm %[output:07dacff1] %[output:913fa74d]
    ax.DataAspectRatioMode ="auto"     %[output:2ede4c24] %[output:15ec1447] %[output:8fe497a3]
    title(tns(iph)) %[output:8fe497a3]
end %[output:group:8e325e14]
%%
%[output:4454792f]
%%
for iph = 1:2 %[output:group:512bc606]
    subplot(2,1,iph) %[output:51a20292]
    views(mapXkills{iph}./mean(mapXkills{iph},2))
    xlabel("E")
    ylabel("y")
    title('x-component averaged')
    colormap bone
end %[output:group:512bc606]
%%
xcut = [0 400 800 1200 size(mapXkills{1},1)];
% p2ind
msb = 2 %[output:2e64499d]
nsb = (size(xcut,2)-1) %[output:282b863e]
for ixcut = 1:nsb %[output:group:252aafe0]
    for iph = 1:2
        p = sub2p([msb nsb],iph,ixcut);
        ax = subplot(2,nsb,p) %[output:519cf51c] %[output:84d4d360] %[output:7b3dd671] %[output:3f975834] %[output:1e2668f9] %[output:38c7732a] %[output:54a49244] %[output:11ea1031] %[output:266f0eda]
        xrng = (xcut(ixcut)+1):xcut(ixcut+1);
        vrng = map.vm(xrng);
        views(mapXkills{iph}(xrng,:)) %[output:266f0eda]
        xlabel("E")
        ylabel("y")       
        colormap bone
        axis normal
        ax.Children.XData =vrng;
    end
end %[output:group:252aafe0]

